138	     *
139	     * @param name to test
140	     * @return true if pet name is already in use
141	     */
142	    public Pet getPet(String name, boolean ignoreNew) {
143	        name = name.toLowerCase();
144	        for (Pet pet : getPetsInternal()) {
145	            if (!ignoreNew || !pet.isNew()) {
146	                String compName = pet.getName();
147	                compName = compName.toLowerCase();
148	                if (compName.equals(name)) {
149	                    return pet;
150	                }
151	            }
152	        }
153	        return null;
154	    }
155	
156	    public Pet getPet(Integer petId) {
157	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
158	    }
