7	/**
8	 * Normalization for the optional owner {@code email}: when present it must be a syntactically
9	 * valid address; it is stored and returned lower-cased. An absent (null/blank) email is left
10	 * untouched. Invalid values raise {@link InvalidOwnerEmailException} so the endpoint responds 400.
11	 */
12	final class OwnerEmail {
13	
14	    /** A pragmatic address check: one {@code @}, non-empty local and domain parts, a dotted domain. */
15	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
16	
17	    private OwnerEmail() {
18	    }
19	
20	    /**
21	     * If the request carries a non-blank email, validate and lower-case it in place; otherwise leave
22	     * it as-is.
23	     */
24	    static void normalize(OwnerFieldsDto request) throws InvalidOwnerEmailException {
25	        String email = request.getEmail();
26	        if (email == null || email.isBlank()) {
27	            return;
28	        }
29	        if (!EMAIL.matcher(email).matches()) {
30	            throw new InvalidOwnerEmailException(email);
31	        }
32	        request.setEmail(email.toLowerCase());
33	    }
34	}
